actions.script:
const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const CODES = {CrtDirect: 'direct', CrtPrivate: 'private', CrtPublic: 'public', CrtRecord: 'record'}
const DEFAULT_VISIBILITY = {CrtDirect: 'CrvMembers', CrtPrivate: 'CrvMembers', CrtPublic: 'CrvUsers', CrtRecord: 'CrvRecord'}
const ROLE_LEVEL = {CmrOwner: 4, CmrModerator: 3, CmrMember: 2, CmrAgent: 2}
level = 0; room = null; member = null
isMember = false; canRead = false; canJoin = false; canPost = false; canModerate = false; isOwner = false; isArchived = false
const currentUserId = ec.user.userId
if (!userId) userId = currentUserId
if (!userId) return
if (userId !== currentUserId && !ec.artifactExecution.authzDisabled()) {
    ec.message.addError(`The chat rooms of user ${userId} are not yours to see`)
    return
}
const row = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).one()
if (!row) return
// an external user (EXTERNAL_USER; a failed check counts as external) reaches no record room, as a member
// neither, and no public room they are not a member of
const external = ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers').parameter('userIdList', [userId])
        .disableAuthz().call()?.anyExternal !== false
if (external && (row.roomTypeEnumId === 'CrtRecord' || row.visibilityEnumId === 'CrvRecord' || row.recordEntityName)) return
const isDirect = row.roomTypeEnumId === 'CrtDirect'
const memberRow = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', userId).one()
isArchived = !!row.archivedDate
if (memberRow && (!memberRow.leftDate || isDirect)) {
    isMember = true
    level = isDirect ? 2 : (ROLE_LEVEL[memberRow.roleEnumId] || 2)
} else {
    const visibility = row.visibilityEnumId || DEFAULT_VISIBILITY[row.roomTypeEnumId] || 'CrvMembers'
    if (visibility === 'CrvUsers') {
        if (!external) level = 1
    } else if (visibility === 'CrvRecord' && row.recordEntityName && row.recordId) {
        // the record's visibility is the app's: asked as the user, with the caller's authorization (another
        // user, internal work only, is asked for as that user)
        const out = ec.service.sync().name('org.moqui.impl.ChatServices.check#RecordVisible')
                .parameters({recordEntityName: row.recordEntityName, recordId: row.recordId,
                    userId: userId !== currentUserId ? userId : null}).call()
        if (out && out.recordVisible === true) level = 1
    }
    canJoin = level === 1 && !isArchived
}
if (level === 0) return
canRead = true
canPost = isMember && !isArchived
canModerate = level >= 3 && !isDirect
isOwner = level >= 4
room = {chatRoomId: row.chatRoomId, roomTypeEnumId: row.roomTypeEnumId ?? null, roomType: CODES[row.roomTypeEnumId] || null,
    roomName: row.roomName ?? null, topic: row.topic ?? null, avatarLocation: row.avatarLocation ?? null,
    visibilityEnumId: row.visibilityEnumId || DEFAULT_VISIBILITY[row.roomTypeEnumId] || 'CrvMembers',
    recordEntityName: row.recordEntityName ?? null, recordId: row.recordId ?? null, retentionDays: row.retentionDays ?? null,
    createdByUserId: row.createdByUserId ?? null, createdDate: toMillis(row.createdDate), archivedDate: toMillis(row.archivedDate),
    lastEventSeq: Number(row.lastEventSeq || 0), lastEventDate: toMillis(row.lastEventDate),
    lastMessageSeq: row.lastMessageSeq != null ? Number(row.lastMessageSeq) : null, lastMessageUserId: row.lastMessageUserId ?? null,
    lastMessageDate: toMillis(row.lastMessageDate), lastMessageSnippet: row.lastMessageSnippet ?? null,
    callE2eeRequired: row.callE2eeRequired === 'Y', encrypted: row.encrypted === 'Y', verifiedDevicesOnly: row.verifiedDevicesOnly === 'Y'}
if (memberRow) member = {chatRoomId: memberRow.chatRoomId, userId: memberRow.userId, chatActorId: memberRow.chatActorId ?? null,
    roleEnumId: memberRow.roleEnumId ?? null,
    agentRef: memberRow.agentRef ?? null, joinedDate: toMillis(memberRow.joinedDate), leftDate: toMillis(memberRow.leftDate),
    lastReadEventSeq: Number(memberRow.lastReadEventSeq || 0), notificationLevelEnumId: memberRow.notificationLevelEnumId ?? null,
    isPinned: memberRow.isPinned === 'Y', isMuted: memberRow.isMuted === 'Y'}

const CODES = {CetMessage: 'message', CetEdit: 'edit', CetReaction: 'reaction', CetRedaction: 'redaction',
    CetMembership: 'membership', CetPin: 'pin', CetCall: 'call', CetPoll: 'poll', CetSystem: 'system'}
const snippetOf = (text, attachments) => {
    const shown = String(text || '').replace(/\s+/g, ' ').trim()
    if (shown) return shown.length > 140 ? shown.slice(0, 139) + '…' : shown
    const files = (attachments || []).map((file) => file.fileName).filter((name) => name)
    return files.length ? '📎 ' + files.join(', ') : ''
}
if (!senderActorId && senderUserId) senderActorId = (ec.service.sync().name('org.moqui.impl.ChatServices.get#LocalActors')
        .parameter('userIdList', [senderUserId]).disableAuthz().call()?.actorMap || {})[senderUserId] || null
const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).forUpdate(true).one()
if (!room) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const now = ec.user.nowTimestamp
eventSeq = Number(room.lastEventSeq || 0) + 1
const row = ec.entity.makeValue('moqui.chat.ChatEvent')
row.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, eventTypeEnumId: eventTypeEnumId, senderUserId: senderUserId || null,
    senderActorId: senderActorId || null,
    contentJson: content ? JSON.stringify(content) : null, bodyText: encrypted ? null : bodyText || null, encrypted: encrypted ? 'Y' : null,
    replyToEventSeq: replyToEventSeq ?? null, threadRootEventSeq: threadRootEventSeq ?? null,
    editsEventSeq: editsEventSeq ?? null, relatesToEventSeq: relatesToEventSeq ?? null, clientRef: clientRef || null, sentDate: now},
    true, null, null)
row.create()
room.set('lastEventSeq', eventSeq)
room.set('lastEventDate', now)
if (eventTypeEnumId === 'CetMessage' && threadRootEventSeq == null) {
    room.set('lastMessageSeq', eventSeq)
    room.set('lastMessageUserId', senderUserId || null)
    room.set('lastMessageActorId', senderActorId || null)
    room.set('lastMessageDate', now)
    room.set('lastMessageSnippet', encrypted ? null : snippetOf(bodyText, content ? content.attachments : null) || null)
}
room.update()

let senderName = null, senderExternal = null
if (senderUserId) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', senderUserId)
            .selectField('userFullName').selectField('username').disableAuthz().one()
    if (account) senderName = account.userFullName || account.username || senderUserId
} else if (senderActorId) {
    const actor = (ec.service.sync().name('org.moqui.impl.ChatServices.get#ActorNames').parameter('chatActorIdList', [senderActorId])
            .call()?.actorMap || {})[senderActorId]
    if (actor) { senderName = actor.name; senderExternal = actor.external ? {network: actor.network, networkName: actor.networkName} : null }
}
const body = content && content.body != null ? content.body : null
event = {chatRoomId: chatRoomId, eventSeq: eventSeq, eventTypeEnumId: eventTypeEnumId, type: CODES[eventTypeEnumId] || null,
    senderUserId: senderUserId || null, senderActorId: senderActorId || null, senderName: senderName, senderExternal: senderExternal,
    sentDate: Number(now), content: content || {},
    body: encrypted ? null : body, bodyText: encrypted ? null : bodyText || null,
    encrypted: encrypted && content ? content.encrypted || null : null, mentions: (content && content.mentions) || [],
    attachments: (content && content.attachments) || [], records: (content && content.records) || [],
    forwardOf: (content && content.forwardOf) || null, poll: null, assist: (content && content.assist) || null, linkPreviews: [],
    replyToEventSeq: replyToEventSeq ?? null, threadRootEventSeq: threadRootEventSeq ?? null,
    editsEventSeq: editsEventSeq ?? null, relatesToEventSeq: relatesToEventSeq ?? null, clientRef: clientRef || null}

const isDirect = room.roomTypeEnumId === 'CrtDirect'
memberUserIdList = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId)
        .selectField('userId').selectField('leftDate').list()).filter((member) => member.userId && (isDirect || !member.leftDate))
        .map((member) => member.userId)
if (!noPush && memberUserIdList.length) {
    ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatRoom:' + chatRoomId,
        userIdList: memberUserIdList, message: {kind: 'event', chatRoomId: chatRoomId, eventSeq: eventSeq, event: event}}).call()
}

// the members' changes feeds: a message changed after it was sent, and a membership. A new message is no change
// (the room's lastEventSeq is its head), nor a system event (update#Room records the room's change)
changeSeqMap = {}
if (!noPush) {
    const about = content || {}
    const changes = []
    const messageChange = (target, cause, extra) => changes.push({userIdList: memberUserIdList, changeKind: 'message',
        chatRoomId: chatRoomId, eventSeq: Number(target), change: Object.assign({cause: cause, causeEventSeq: eventSeq}, extra || {})})
    if (eventTypeEnumId === 'CetEdit' && editsEventSeq != null) messageChange(editsEventSeq, 'edit')
    else if (eventTypeEnumId === 'CetReaction' && relatesToEventSeq != null) messageChange(relatesToEventSeq, 'reaction')
    else if (eventTypeEnumId === 'CetPin' && relatesToEventSeq != null) messageChange(relatesToEventSeq, 'pin')
    else if (eventTypeEnumId === 'CetRedaction' && relatesToEventSeq != null) {
        if (about.target === 'reaction') { if (about.messageSeq != null) messageChange(about.messageSeq, 'reaction') }
        else messageChange(relatesToEventSeq, 'redaction', {redacted: true})
    } else if (eventTypeEnumId === 'CetMembership') {
        changes.push({userIdList: memberUserIdList, changeKind: 'room', chatRoomId: chatRoomId, eventSeq: eventSeq, change: {reason: 'members'}})
        const action = {join: 'joined', add: 'joined', leave: 'left', remove: 'left', role: 'role'}[about.action]
        if (about.userId && action) changes.push({userIdList: [about.userId], changeKind: 'membership', chatRoomId: chatRoomId,
            eventSeq: eventSeq, change: {action: action, roleEnumId: about.roleEnumId ?? null, byUserId: about.byUserId ?? null}})
    }
    if (changes.length) {
        changeSeqMap = ec.service.sync().name('org.moqui.impl.ChatServices.record#UserChange').parameter('changeList', changes)
                .call()?.changeSeqMap || {}
        if (ec.message.hasError()) return
    }
}

// the bridges it goes out to: a delivery row per mapping, in this transaction (C1)
const BRIDGED = ['CetMessage', 'CetEdit', 'CetReaction', 'CetRedaction']
if (BRIDGED.includes(eventTypeEnumId) && !encrypted && room.encrypted !== 'Y') {
    const mappings = Array.from(ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatRoomId', chatRoomId).condition('thruDate', null)
            .condition('directionEnumId', 'in', ['CrbBoth', 'CrbOut']).disableAuthz().list())
            .filter((mapping) => !sourceChatBridgeId || mapping.chatBridgeId !== sourceChatBridgeId)
    const target = eventTypeEnumId === 'CetEdit' ? editsEventSeq : eventTypeEnumId === 'CetMessage' ? null : relatesToEventSeq
    let queued = 0
    for (const mapping of mappings) {
        let dependsOn = null
        if (target != null) {
            // an edit, reaction or delete goes where what it is about went, or came from
            const prior = ec.entity.find('moqui.chat.ChatBridgeDelivery').condition('chatRoomId', chatRoomId).condition('eventSeq', target)
                    .condition('chatRoomBridgeId', mapping.chatRoomBridgeId).disableAuthz().one()
            if (prior) dependsOn = prior.chatBridgeDeliveryId
            else if (!ec.entity.find('moqui.chat.ChatEventExternal').condition('chatRoomId', chatRoomId).condition('eventSeq', target)
                    .condition('chatBridgeId', mapping.chatBridgeId).disableAuthz().count()) continue
        }
        const delivery = ec.entity.makeValue('moqui.chat.ChatBridgeDelivery')
        delivery.setSequencedIdPrimary()
        delivery.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, chatRoomBridgeId: mapping.chatRoomBridgeId,
            chatBridgeId: mapping.chatBridgeId, idempotencyKey: `moqui-chat:${chatRoomId}:${eventSeq}:${mapping.chatRoomBridgeId}`,
            dependsOnDeliveryId: dependsOn, statusEnumId: 'CdsPending', attemptCount: 0, createdDate: now}, true, null, null)
        delivery.create()
        queued++
    }
    if (queued) ec.service.sync().name('org.moqui.impl.ChatServices.wake#BridgeDelivery').disableAuthz().call()
}

const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).one()
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).one()
if (!room || !row) return
const isDirect = room.roomTypeEnumId === 'CrtDirect'
const users = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId)
        .selectField('userId').selectField('leftDate').list()).filter((member) => member.userId && (isDirect || !member.leftDate))
        .map((member) => member.userId)
if (users.length) ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatRoom:' + chatRoomId,
    userIdList: users, message: {kind: 'update', chatRoomId: chatRoomId, eventSeq: eventSeq,
    threadRootEventSeq: row.threadRootEventSeq != null ? Number(row.threadRootEventSeq) : null, fields: fields}}).call()
ec.service.sync().name('org.moqui.impl.ChatServices.record#UserChange').parameters({userIdList: users, changeKind: 'message',
    chatRoomId: chatRoomId, eventSeq: eventSeq, change: {cause: 'update'}}).call()

const KINDS = {membership: 'CucMembership', room: 'CucRoom', settings: 'CucSettings', read: 'CucRead', message: 'CucMessage',
    retention: 'CucRetention'}
changeSeqMap = {}
const entries = []
const add = (entry) => {
    const kind = KINDS[entry.changeKind] || entry.changeKind
    if (!Object.values(KINDS).includes(kind)) { ec.message.addError(`Unknown chat change kind ${entry.changeKind}`); return false }
    const users = Array.from(new Set(Array.from(entry.userIdList || []).map((id) => String(id || '').trim()).filter((id) => id)))
    if (users.length) entries.push({users: users, kind: kind, chatRoomId: entry.chatRoomId || null,
        eventSeq: entry.eventSeq != null ? Number(entry.eventSeq) : null, json: entry.change ? JSON.stringify(entry.change) : null})
    return true
}
if (changeKind && !add({userIdList: userIdList, changeKind: changeKind, chatRoomId: chatRoomId, eventSeq: eventSeq, change: change})) return
for (const entry of Array.from(changeList || [])) if (entry && !add(entry)) return
const users = Array.from(new Set(entries.flatMap((entry) => entry.users))).sort()
if (!users.length) return

// each user's counter, locked in userId order; a missing one is made with an insert that waits for another's
const lock = () => {
    const found = {}
    for (let start = 0; start < users.length; start += 500)
        for (const row of ec.entity.find('moqui.chat.ChatUserState').condition('userId', 'in', users.slice(start, start + 500))
                .orderBy('userId').forUpdate(true).disableAuthz().list()) found[row.userId] = row
    return found
}
let states = lock()
const missing = users.filter((id) => !states[id])
if (missing.length) {
    for (const id of missing) {
        const state = ec.entity.makeValue('moqui.chat.ChatUserState')
        state.set('userId', id)
        state.createOrUpdate()
    }
    states = lock()
}
const now = ec.user.nowTimestamp
for (const entry of entries) {
    // the earlier change of the same thing: this one stands for it
    for (let start = 0; start < entry.users.length; start += 500) {
        let earlier = ec.entity.find('moqui.chat.ChatUserChange').condition('userId', 'in', entry.users.slice(start, start + 500))
                .condition('chatRoomId', entry.chatRoomId).condition('changeKindEnumId', entry.kind)
        if (entry.kind === 'CucMessage') earlier = earlier.condition('eventSeq', entry.eventSeq)
        earlier.disableAuthz().deleteAll()
    }
    for (const id of entry.users) {
        const state = states[id]
        if (!state) { ec.message.addError(`No chat change counter for user ${id}`); return }
        const seq = Number(state.lastChangeSeq || 0) + 1
        state.set('lastChangeSeq', seq)
        const row = ec.entity.makeValue('moqui.chat.ChatUserChange')
        row.setFields({userId: id, changeSeq: seq, changeKindEnumId: entry.kind, chatRoomId: entry.chatRoomId,
            eventSeq: entry.eventSeq, changeJson: entry.json, changeDate: now}, true, null, null)
        row.create()
        changeSeqMap[id] = seq
    }
}
for (const id of users) if (changeSeqMap[id] != null) states[id].update()
if (pushMessage) for (const id of users) {
    if (changeSeqMap[id] == null) continue
    ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatUser:' + id, userIdList: [id],
        message: Object.assign({}, pushMessage, {changeSeq: changeSeqMap[id]})}).call()
}

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
const CODES = {CucMembership: 'membership', CucRoom: 'room', CucSettings: 'settings', CucRead: 'read', CucMessage: 'message',
    CucRetention: 'retention'}
changeList = []; lastSeq = 0; more = false; reset = false; headList = null
const me = ec.user.userId
if (!me) { ec.message.addError(ec.l10n.localize('No user')); return }
// the counter first: a change committed after it is still in the rows read next
const state = ec.entity.find('moqui.chat.ChatUserState').condition('userId', me).disableAuthz().one()
const last = Number((state && state.lastChangeSeq) || 0)
const purged = Number((state && state.purgedChangeSeq) || 0)
if (afterSeq == null || Number(afterSeq) < purged || Number(afterSeq) > last) {
    reset = true
    lastSeq = last
} else {
    const size = Math.max(1, Math.min(1000, Number(limit) || 200))
    const rows = Array.from(ec.entity.find('moqui.chat.ChatUserChange').condition('userId', me)
            .condition('changeSeq', 'greater', Number(afterSeq)).orderBy('changeSeq').limit(size + 1).disableAuthz().list())
    more = rows.length > size
    changeList = rows.slice(0, size).map((row) => ({changeSeq: Number(row.changeSeq), kind: CODES[row.changeKindEnumId] || null,
        chatRoomId: row.chatRoomId ?? null, eventSeq: row.eventSeq != null ? Number(row.eventSeq) : null,
        changeDate: toMillis(row.changeDate), data: parse(row.changeJson)}))
    lastSeq = changeList.length ? changeList[changeList.length - 1].changeSeq : Number(afterSeq)
}
if (more || !heads) return
headList = []
const members = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).condition('leftDate', null)
        .selectField('chatRoomId').selectField('lastReadEventSeq').disableAuthz().list())
const readOf = {}
for (const row of members) readOf[row.chatRoomId] = Number(row.lastReadEventSeq || 0)
const ids = Object.keys(readOf)
for (let start = 0; start < ids.length; start += 500)
    for (const room of ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', ids.slice(start, start + 500))
            .selectField('chatRoomId').selectField('lastEventSeq').selectField('lastMessageSeq').selectField('lastEventDate')
            .orderBy('chatRoomId').disableAuthz().list())
        headList.push({chatRoomId: room.chatRoomId, lastEventSeq: Number(room.lastEventSeq || 0),
            lastMessageSeq: room.lastMessageSeq != null ? Number(room.lastMessageSeq) : null, lastEventDate: toMillis(room.lastEventDate),
            lastReadEventSeq: readOf[room.chatRoomId]})

userCount = 0; deletedCount = 0; failedCount = 0
const days = keepDays != null ? Number(keepDays) : Number(System.getProperty('chat_changes_keep_days') || 30)
const before = beforeDate != null ? Number(beforeDate) : Number(ec.user.nowTimestamp) - Math.max(1, days || 30) * 86400000
let find = ec.entity.find('moqui.chat.ChatUserChange').condition('changeDate', 'less', String(before))
if (userIdList && Array.from(userIdList).length) find = find.condition('userId', 'in', Array.from(userIdList))
const users = Array.from(find.selectField('userId').distinct(true).disableAuthz().list()).map((row) => row.userId)
for (const userId of users) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.ChatServices.purge#UserChanges').parameters({userId: userId, beforeDate: before})
                .requireNewTransaction(true).disableAuthz().call()
        if (ec.message.hasError()) {
            failedCount++
            ec.logger.error(`Could not clean the chat changes of user ${userId}: ${ec.message.errorsString}`)
        } else {
            userCount++
            deletedCount += Number((out && out.deletedCount) || 0)
        }
    } catch (err) {
        failedCount++
        ec.logger.error(`Could not clean the chat changes of user ${userId}: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
if (deletedCount || failedCount) ec.logger.info(`Chat changes: ${deletedCount} removed for ${userCount} users, ${failedCount} users failed`)

deletedCount = 0
const state = ec.entity.find('moqui.chat.ChatUserState').condition('userId', userId).forUpdate(true).disableAuthz().one()
if (!state) return
const old = Array.from(ec.entity.find('moqui.chat.ChatUserChange').condition('userId', userId)
        .condition('changeDate', 'less', String(beforeDate)).orderBy('-changeSeq').limit(1).selectField('changeSeq').disableAuthz().list())
if (!old.length) return
const through = Number(old[0].changeSeq)
if (through > Number(state.purgedChangeSeq || 0)) {
    state.set('purgedChangeSeq', through)
    state.set('purgedDate', ec.user.nowTimestamp)
    state.update()
}
deletedCount = ec.entity.find('moqui.chat.ChatUserChange').condition('userId', userId).condition('changeSeq', 'less-equals', through)
        .disableAuthz().deleteAll()

actorMap = {}
const ids = Array.from(new Set(Array.from(chatActorIdList || []).map((id) => String(id || '').trim()).filter((id) => id)))
if (!ids.length) return
const actors = Array.from(ec.entity.find('moqui.chat.ChatActor').condition('chatActorId', 'in', ids).disableAuthz().list())
const userIds = actors.map((row) => row.userId).filter((id) => id)
const externalIds = actors.map((row) => row.chatExternalUserId).filter((id) => id)
const names = {}
if (userIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds)
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
const externals = {}, bridgeIds = new Set()
if (externalIds.length) for (const row of ec.entity.find('moqui.chat.ChatExternalUser').condition('chatExternalUserId', 'in', externalIds)
        .disableAuthz().list()) { externals[row.chatExternalUserId] = row; if (row.chatBridgeId) bridgeIds.add(row.chatBridgeId) }
const networks = {}
if (bridgeIds.size) {
    const bridges = Array.from(ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', 'in', Array.from(bridgeIds))
            .selectField('chatBridgeId').selectField('typeEnumId').disableAuthz().list())
    const types = {}
    const typeIds = Array.from(new Set(bridges.map((row) => row.typeEnumId).filter((id) => id)))
    if (typeIds.length) for (const row of ec.entity.find('moqui.basic.Enumeration').condition('enumId', 'in', typeIds).disableAuthz().list())
        types[row.enumId] = row
    for (const row of bridges) networks[row.chatBridgeId] = {network: types[row.typeEnumId]?.enumCode || null,
        networkName: types[row.typeEnumId]?.description || null}
}
for (const row of actors) {
    if (row.userId) {
        actorMap[row.chatActorId] = {chatActorId: row.chatActorId, userId: row.userId, name: names[row.userId] || row.userId,
            external: false, network: null, networkName: null, chatBridgeId: null}
    } else {
        const external = externals[row.chatExternalUserId] || {}
        const network = networks[external.chatBridgeId] || {}
        actorMap[row.chatActorId] = {chatActorId: row.chatActorId, userId: null,
            name: external.displayName || external.externalUserId || row.chatActorId, external: true,
            network: network.network || null, networkName: network.networkName || null, chatBridgeId: external.chatBridgeId || null}
    }
}

bridgeMap = {}; capabilityMap = {}
const ids = Array.from(new Set(Array.from(chatRoomIdList || []).map((id) => String(id || '').trim()).filter((id) => id)))
if (!ids.length) return
const mappings = Array.from(ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatRoomId', 'in', ids).condition('thruDate', null)
        .disableAuthz().list())
if (!mappings.length) return
const bridgeIds = Array.from(new Set(mappings.map((row) => row.chatBridgeId)))
const bridges = {}
for (const row of ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', 'in', bridgeIds).disableAuthz().list()) bridges[row.chatBridgeId] = row
const types = {}
const typeIds = Array.from(new Set(Object.values(bridges).map((row) => row.typeEnumId).filter((id) => id)))
if (typeIds.length) for (const row of ec.entity.find('moqui.basic.Enumeration').condition('enumId', 'in', typeIds).disableAuthz().list()) types[row.enumId] = row
const caps = ec.service.sync().name('org.moqui.impl.ChatServices.get#BridgeCapabilities').parameter('chatBridgeIdList', bridgeIds)
        .disableAuthz().call()?.capabilityMap || {}
for (const row of mappings) {
    const bridge = bridges[row.chatBridgeId] || {}
    const outbound = row.directionEnumId !== 'CrbIn'
