        chatBridgeId: row.chatBridgeId, name: bridge.name ?? null, network: types[bridge.typeEnumId]?.enumCode || null,
        networkName: types[bridge.typeEnumId]?.description || null, statusId: bridge.statusId ?? null,
        connected: bridge.statusId === 'CbsConnected', externalRoomName: row.externalRoomName ?? null,
        externalRoomUrl: row.externalRoomUrl ?? null, directionEnumId: row.directionEnumId ?? null, outbound: outbound})
    const cap = caps[row.chatBridgeId] || {}
    const room = capabilityMap[row.chatRoomId] = capabilityMap[row.chatRoomId] || {edit: true, delete: true, reaction: true}
    if (outbound) { room.edit = room.edit && cap.edit === true; room.delete = room.delete && cap.delete === true
        room.reaction = room.reaction && cap.reaction === true }
}

supported = true; reasonCode = null; bridgeName = null
const bridgeIds = new Set()
for (const row of ec.entity.find('moqui.chat.ChatBridgeDelivery').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq)
        .selectField('chatBridgeId').disableAuthz().list()) bridgeIds.add(row.chatBridgeId)
for (const row of ec.entity.find('moqui.chat.ChatEventExternal').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq)
        .selectField('chatBridgeId').disableAuthz().list()) bridgeIds.add(row.chatBridgeId)
if (!bridgeIds.size) return
// only the bridges the room still sends to
const live = new Set(Array.from(ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatRoomId', chatRoomId).condition('thruDate', null)
        .condition('directionEnumId', 'in', ['CrbBoth', 'CrbOut']).selectField('chatBridgeId').disableAuthz().list()).map((row) => row.chatBridgeId))
const ids = Array.from(bridgeIds).filter((id) => live.has(id))
if (!ids.length) return
const caps = ec.service.sync().name('org.moqui.impl.ChatServices.get#BridgeCapabilities').parameter('chatBridgeIdList', ids)
        .disableAuthz().call()?.capabilityMap || {}
for (const id of ids) {
    if ((caps[id] || {})[operation] === true) continue
    supported = false
    reasonCode = 'bridgeUnsupported'
    bridgeName = ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', id).disableAuthz().one()?.name || id
    return
}

try {
    if (!ec.search.isAvailable()) return
    if (!remove && ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq)
            .condition('encrypted', 'Y').disableAuthz().count()) return
    if (remove) ec.search.deleteDocument('MoquiChatEvent', `${chatRoomId}::${eventSeq}`)
    else ec.search.indexDocuments(ec.entity.getDataDocuments('MoquiChatEvent', {chatRoomId: chatRoomId, eventSeq: eventSeq}))
} catch (err) {
    ec.logger.error(`Could not ${remove ? 'remove' : 'index'} chat message ${chatRoomId}::${eventSeq} in the search index: ${err && err.message ? err.message : err}`)
}

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const CODES = {CrtDirect: 'direct', CrtPrivate: 'private', CrtPublic: 'public', CrtRecord: 'record'}
const DEFAULT_VISIBILITY = {CrtDirect: 'CrvMembers', CrtPrivate: 'CrvMembers', CrtPublic: 'CrvUsers', CrtRecord: 'CrvRecord'}
roomList = []; unreadTotal = 0; mentionTotal = 0
const currentUserId = ec.user.userId
if (!userId) userId = currentUserId
if (!userId) return
if (userId !== currentUserId && !ec.artifactExecution.authzDisabled()) {
    ec.message.addError(`The chat rooms of user ${userId} are not yours to see`); return }
// an external user (EXTERNAL_USER; a failed check counts as external): no record room, no public room to join
const external = ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers').parameter('userIdList', [userId])
        .disableAuthz().call()?.anyExternal !== false
const memberRows = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', userId).condition('leftDate', null).list())
const memberOf = {}
for (const row of memberRows) memberOf[row.chatRoomId] = row
const roomIds = Object.keys(memberOf)
let rooms = []
if (roomIds.length) {
    let find = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', roomIds)
    if (!includeArchived) find = find.condition('archivedDate', null)
    if (recordEntityName) find = find.condition('recordEntityName', recordEntityName)
    if (recordId) find = find.condition('recordId', recordId)
    rooms = Array.from(find.list())
    if (external) rooms = rooms.filter((row) => !(row.roomTypeEnumId === 'CrtRecord' || row.visibilityEnumId === 'CrvRecord' || row.recordEntityName))
}
if (includeJoinable && filter !== 'direct' && !external) {
    let find = ec.entity.find('moqui.chat.ChatRoom').condition('visibilityEnumId', 'CrvUsers').condition('archivedDate', null)
    if (roomIds.length) find = find.condition('chatRoomId', 'not-in', roomIds)
    if (recordEntityName) find = find.condition('recordEntityName', recordEntityName)
    if (recordId) find = find.condition('recordId', recordId)
    for (const row of find.orderBy('-lastEventDate').limit(200).list()) rooms.push(row)
}
// the members of the direct rooms, for their names
const directIds = rooms.filter((row) => row.roomTypeEnumId === 'CrtDirect').map((row) => row.chatRoomId)
const directMembers = {}
if (directIds.length) {
    for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', directIds).selectField('chatRoomId')
            .selectField('userId').orderBy('joinedDate').list()) if (row.userId) (directMembers[row.chatRoomId] = directMembers[row.chatRoomId] || []).push(row.userId)
}
const userIds = new Set([userId])
for (const ids of Object.values(directMembers)) ids.forEach((id) => userIds.add(id))
rooms.forEach((row) => { if (row.lastMessageUserId) userIds.add(row.lastMessageUserId) })
const names = {}
for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', Array.from(userIds))
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
// an external actor's last message: its name; the connectors of the rooms (C1)
const externalLast = rooms.filter((row) => !row.lastMessageUserId && row.lastMessageActorId).map((row) => row.lastMessageActorId)
const actorNames = externalLast.length ? ec.service.sync().name('org.moqui.impl.ChatServices.get#ActorNames')
        .parameter('chatActorIdList', externalLast).call()?.actorMap || {} : {}
const bridgeMap = rooms.length ? ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomBridges')
        .parameter('chatRoomIdList', rooms.map((row) => row.chatRoomId)).call()?.bridgeMap || {} : {}
// the unread messages and the mentions of every room the user is in, in one query each
const unreadOf = {}, mentionsOf = {}
if (roomIds.length) {
    for (const count of ec.entity.find('moqui.chat.ChatMemberUnread').condition('userId', userId).condition('leftDate', null)
            .condition('redactedDate', null).selectField('chatRoomId').selectField('unreadCount').list())
        unreadOf[count.chatRoomId] = Number(count.unreadCount || 0)
    for (const count of ec.entity.find('moqui.chat.ChatMemberMentions').condition('userId', userId).condition('leftDate', null)
            .selectField('chatRoomId').selectField('mentionCount').list())
        mentionsOf[count.chatRoomId] = Number(count.mentionCount || 0)
}
const presenceUsers = new Set()
const text = searchText ? String(searchText).toLowerCase().trim() : ''
for (const row of rooms) {
    const member = memberOf[row.chatRoomId] || null
    const isDirect = row.roomTypeEnumId === 'CrtDirect'
    const lastRead = member ? Number(member.lastReadEventSeq || 0) : 0
    const unreadCount = member ? unreadOf[row.chatRoomId] || 0 : 0
    const mentionCount = member ? mentionsOf[row.chatRoomId] || 0 : 0
    const others = isDirect ? (directMembers[row.chatRoomId] || []).filter((id) => id !== userId) : []
    const displayName = row.roomName || (isDirect ? (others.length ? others.map((id) => names[id] || id).join(', ') : names[userId] || userId) : row.chatRoomId)
    const item = {chatRoomId: row.chatRoomId, roomTypeEnumId: row.roomTypeEnumId ?? null, roomType: CODES[row.roomTypeEnumId] || null,
        roomName: row.roomName ?? null, displayName: displayName, topic: row.topic ?? null, avatarLocation: row.avatarLocation ?? null,
        visibilityEnumId: row.visibilityEnumId || DEFAULT_VISIBILITY[row.roomTypeEnumId] || 'CrvMembers',
        recordEntityName: row.recordEntityName ?? null, recordId: row.recordId ?? null, archivedDate: toMillis(row.archivedDate),
        lastEventSeq: Number(row.lastEventSeq || 0), lastEventDate: toMillis(row.lastEventDate) || toMillis(row.createdDate),
        isMember: !!member, roleEnumId: member ? member.roleEnumId ?? null : null,
        notificationLevelEnumId: member ? member.notificationLevelEnumId ?? null : null,
        isPinned: !!member && member.isPinned === 'Y', isMuted: !!member && member.isMuted === 'Y',
        lastReadEventSeq: lastRead, unreadCount: unreadCount, mentionCount: mentionCount,
        lastMessage: row.lastMessageSeq != null ? {eventSeq: Number(row.lastMessageSeq), senderUserId: row.lastMessageUserId ?? null,
            senderName: row.lastMessageUserId ? names[row.lastMessageUserId] || row.lastMessageUserId
                : (actorNames[row.lastMessageActorId]?.name ?? null),
            sentDate: toMillis(row.lastMessageDate), snippet: row.lastMessageSnippet ?? null, redacted: row.encrypted !== 'Y' && row.lastMessageSnippet == null, encrypted: row.encrypted === 'Y'} : null,
        encrypted: row.encrypted === 'Y',
        otherUserIdList: others, otherUserId: others.length === 1 ? others[0] : null, presence: null,
        bridged: !!bridgeMap[row.chatRoomId], notConnected: (bridgeMap[row.chatRoomId] || []).some((bridge) => !bridge.connected),
        bridgeNetworkNames: Array.from(new Set((bridgeMap[row.chatRoomId] || []).map((bridge) => bridge.networkName).filter((name) => name)))}
    if (text && !(`${displayName} ${row.topic || ''}`.toLowerCase().includes(text))) continue
    if (filter === 'unread' && !(unreadCount > 0 || mentionCount > 0)) continue
    if (filter === 'mentions' && !(mentionCount > 0)) continue
    if (filter === 'direct' && !isDirect) continue
    if (filter === 'rooms' && !(row.roomTypeEnumId === 'CrtPrivate' || row.roomTypeEnumId === 'CrtPublic')) continue
    if (filter === 'records' && row.roomTypeEnumId !== 'CrtRecord') continue
    if (item.otherUserId) presenceUsers.add(item.otherUserId)
    roomList.push(item)
}
roomList.sort((left, right) => {
    if (left.isMember !== right.isMember) return left.isMember ? -1 : 1
    if (left.isPinned !== right.isPinned) return left.isPinned ? -1 : 1
    const byDate = (right.lastEventDate || 0) - (left.lastEventDate || 0)
    return byDate !== 0 ? byDate : String(left.chatRoomId).localeCompare(String(right.chatRoomId))
})
if (limit != null && roomList.length > limit) roomList = roomList.slice(0, limit)
if (presenceUsers.size) {
    const statuses = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses')
            .parameter('userIdList', Array.from(presenceUsers)).call()
    const statusMap = (statuses && statuses.statusMap) || {}
    for (const item of roomList) if (item.otherUserId && statusMap[item.otherUserId]) item.presence = statusMap[item.otherUserId].presence
}
for (const item of roomList) { unreadTotal += item.unreadCount; mentionTotal += item.mentionCount }

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
room = null; member = null; access = null; memberList = []
const byRecord = !chatRoomId
if (!chatRoomId) {
    if (!recordEntityName || !recordId) { ec.message.addError(ec.l10n.localize('A chat room is named by chatRoomId, or by recordEntityName and recordId')); return }
    const bound = Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('roomTypeEnumId', 'CrtRecord')
            .condition('recordEntityName', recordEntityName).condition('recordId', recordId).orderBy('createdDate').list())
    if (!bound.length) return
    chatRoomId = (bound.find((row) => !row.archivedDate) || bound[0]).chatRoomId
}
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!out.canRead) { if (!byRecord) ec.message.addError(`Chat room ${chatRoomId} not found`); return }
room = out.room
member = out.member
access = {level: out.level, isMember: out.isMember, canRead: out.canRead, canJoin: out.canJoin, canPost: out.canPost,
    canModerate: out.canModerate, isOwner: out.isOwner, isArchived: out.isArchived}
const isDirect = room.roomTypeEnumId === 'CrtDirect'
const rows = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).orderBy('joinedDate').list())
        .filter((row) => isDirect || !row.leftDate)
const names = {}
const localIds = rows.map((row) => row.userId).filter((id) => id)
if (localIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', localIds)
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
// an external actor of a bridge: its name and network (C1)
const externalIds = rows.filter((row) => !row.userId).map((row) => row.chatActorId)
const actors = externalIds.length ? ec.service.sync().name('org.moqui.impl.ChatServices.get#ActorNames')
        .parameter('chatActorIdList', externalIds).call()?.actorMap || {} : {}
// the read marker of a member who turned read receipts off is not shown to others
const me = ec.user.userId
const others = localIds.filter((id) => id !== me)
const receiptsOff = new Set(others.length ? ec.service.sync().name('org.moqui.impl.ChatServices.get#ReceiptsOffUsers')
        .parameter('userIdList', others).call().offUserIdList || [] : [])
memberList = rows.map((row) => {
    const actor = row.userId ? null : actors[row.chatActorId] || {}
    return {userId: row.userId ?? null, chatActorId: row.chatActorId ?? null,
        name: row.userId ? names[row.userId] || row.userId : actor.name || row.chatActorId, roleEnumId: row.roleEnumId ?? null,
        joinedDate: toMillis(row.joinedDate), lastReadEventSeq: !row.userId || receiptsOff.has(row.userId) ? null : Number(row.lastReadEventSeq || 0),
        isAgent: row.roleEnumId === 'CmrAgent', external: !row.userId, network: actor ? actor.network ?? null : null,
        networkName: actor ? actor.networkName ?? null : null}
})
// its connectors
const bridgesOut = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomBridges').parameter('chatRoomIdList', [chatRoomId]).call()
room.bridges = (bridgesOut?.bridgeMap || {})[chatRoomId] || []
room.bridged = room.bridges.length > 0
room.notConnected = room.bridges.some((bridge) => !bridge.connected)
room.bridgeCapabilities = (bridgesOut?.capabilityMap || {})[chatRoomId] || {edit: true, delete: true, reaction: true}

const TYPES = {direct: 'CrtDirect', private: 'CrtPrivate', public: 'CrtPublic', record: 'CrtRecord'}
const VISIBILITIES = {members: 'CrvMembers', users: 'CrvUsers', record: 'CrvRecord'}
const DEFAULT_VISIBILITY = {CrtDirect: 'CrvMembers', CrtPrivate: 'CrvMembers', CrtPublic: 'CrvUsers', CrtRecord: 'CrvRecord'}
chatRoomId = null; created = false; reasonCode = null
const userId = ec.user.userId
if (!userId) { ec.message.addError(ec.l10n.localize('No user to make a chat room for')); return }
const type = TYPES[roomTypeEnumId] || roomTypeEnumId
if (!Object.values(TYPES).includes(type)) { ec.message.addError(`Unknown chat room type ${roomTypeEnumId}`); return }
// an encrypted room (C7) is for its members: direct or private
if (encrypted && !['CrtDirect', 'CrtPrivate'].includes(type)) { reasonCode = 'encryptedRoom'
    ec.message.addError(ec.l10n.localize('An encrypted room is a direct or private room: public and record rooms are not encrypted')); return }
let visibility = VISIBILITIES[visibilityEnumId] || visibilityEnumId || DEFAULT_VISIBILITY[type]
if (type === 'CrtDirect' || type === 'CrtPrivate') visibility = 'CrvMembers'
else if (type === 'CrtPublic') visibility = 'CrvUsers'
else if (!['CrvMembers', 'CrvRecord'].includes(visibility)) visibility = 'CrvRecord'
const others = Array.from(new Set((memberUserIdList || []).map((id) => String(id || '').trim()).filter((id) => id && id !== userId)))
if (others.length) {
    const found = new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', others)
            .condition(ec.entity.conditionFactory.makeCondition('disabled', 'not-equals', 'Y', true))
            .selectField('userId').disableAuthz().list()).map((row) => row.userId))
    const missing = others.filter((id) => !found.has(id))
    if (missing.length) { ec.message.addError(`User ${missing.join(', ')} not found`); return }
}
const now = ec.user.nowTimestamp
const roomLevel = type === 'CrtPublic' ? 'CnlMentions' : 'CnlAll'
// each member's own default level (CHAT_NOTIFY_DEFAULT), but in a direct room, whose messages always count
const ownLevels = type === 'CrtDirect' ? {} : ec.service.sync().name('org.moqui.impl.ChatServices.get#DefaultNotifyLevels')
        .parameter('userIdList', [userId].concat(others)).call().levelMap || {}
const levelFor = (memberId) => ownLevels[memberId] || roomLevel
const pushRoom = (users, action) => ec.service.sync().name('org.moqui.impl.ChatServices.record#UserChange').parameters({userIdList: users,
    changeKind: 'membership', chatRoomId: chatRoomId, change: {action: action, byUserId: userId},
    pushMessage: {kind: 'room', action: action, chatRoomId: chatRoomId}}).call()
let directKey = null
if (type === 'CrtDirect') {
    directKey = (encrypted ? 'e2ee:' : '') + [userId].concat(others).sort().join(',')
    const existing = ec.entity.find('moqui.chat.ChatRoom').condition('roomTypeEnumId', 'CrtDirect').condition('directKey', directKey)
            .orderBy('createdDate').limit(1).list()
    if (existing.length) {
        chatRoomId = existing[0].chatRoomId
        const mine = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', userId).one()
        if (mine && mine.leftDate) { mine.set('leftDate', null); mine.update(); pushRoom([userId], 'joined') }
        return
    }
} else if (type === 'CrtRecord') {
    if (!recordEntityName || !recordId) { ec.message.addError(ec.l10n.localize('A record room needs recordEntityName and recordId')); return }
    const internal = ec.artifactExecution.authzDisabled()
    if (!internal) {
        const check = ec.service.sync().name('org.moqui.impl.ChatServices.check#RecordVisible')
                .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
        if (!check || check.recordVisible !== true) { ec.message.addError(`Record ${recordEntityName} ${recordId} not found`); return }
    }
    const existing = Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('roomTypeEnumId', 'CrtRecord')
            .condition('recordEntityName', recordEntityName).condition('recordId', recordId).orderBy('createdDate').list())
    const open = existing.find((row) => !row.archivedDate)
    if (open) {
        chatRoomId = open.chatRoomId
        const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
        if (ec.message.hasError()) return
        if (access.canJoin) ec.service.sync().name('org.moqui.impl.ChatServices.add#Member').parameter('chatRoomId', chatRoomId).call()
        else if (!access.canRead) { ec.message.addError(ec.l10n.localize('The room of this record is for its members')); chatRoomId = null }
        return
    }
} else if (!roomName || !String(roomName).trim()) {
    ec.message.addError(ec.l10n.localize('A room needs a name')); return
}
// nobody external (EXTERNAL_USER) is in a room bound to a record, its maker neither
if (type === 'CrtRecord') {
    const outside = ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers').parameter('userIdList', [userId].concat(others))
            .disableAuthz().call()
    if (!outside || outside.anyExternal !== false) { ec.message.addError(`User ${(outside?.externalUserIdList || [userId]).join(', ')} may not be in a record room`); return }
}
const room = ec.entity.makeValue('moqui.chat.ChatRoom')
room.setSequencedIdPrimary()
room.setFields({roomTypeEnumId: type, roomName: roomName ? String(roomName).trim() : (type === 'CrtRecord' ? recordId : null),
    topic: topic || null, avatarLocation: avatarLocation || null, visibilityEnumId: visibility,
    recordEntityName: type === 'CrtRecord' ? recordEntityName : null, recordId: type === 'CrtRecord' ? recordId : null,
    directKey: directKey, retentionDays: retentionDays ?? null, createdByUserId: userId, createdDate: now,
    lastEventSeq: 0, lastEventDate: now, encrypted: encrypted ? 'Y' : null}, true, null, null)
room.create()
chatRoomId = room.chatRoomId
created = true
const members = [userId].concat(others)
const actorOf = ec.service.sync().name('org.moqui.impl.ChatServices.get#LocalActors').parameter('userIdList', members)
        .disableAuthz().call()?.actorMap || {}
for (const memberId of members) {
    const member = ec.entity.makeValue('moqui.chat.ChatRoomMember')
    member.setFields({chatRoomId: chatRoomId, chatActorId: actorOf[memberId], userId: memberId,
        roleEnumId: type === 'CrtDirect' || memberId !== userId ? 'CmrMember' : 'CmrOwner', joinedDate: now, lastReadEventSeq: 0,
        notificationLevelEnumId: levelFor(memberId), isPinned: 'N', isMuted: 'N', addedByUserId: userId}, true, null, null)
    member.create()
}
if (type !== 'CrtDirect') {
    const appended = ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
        eventTypeEnumId: 'CetSystem', senderUserId: userId, content: {action: 'created', roomName: room.roomName ?? null,
        userIds: members, encrypted: !!encrypted}, noPush: true}).call()
    if (ec.message.hasError()) return
    ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).updateAll({lastReadEventSeq: appended.eventSeq})
}
pushRoom(members, 'joined')

const LEVELS = {all: 'CnlAll', mentions: 'CnlMentions', none: 'CnlNone'}
levelMap = {}
const ids = Array.from(new Set(Array.from(userIdList || []).map((id) => String(id || '').trim()).filter((id) => id)))
if (!ids.length) return
for (const row of ec.entity.find('moqui.security.UserPreference').condition('userId', 'in', ids)
        .condition('preferenceKey', 'CHAT_NOTIFY_DEFAULT').disableAuthz().list()) {
    const level = LEVELS[String(row.preferenceValue || '').trim()]
    if (level) levelMap[row.userId] = level
}

const ids = Array.from(new Set(Array.from(userIdList || []).map((id) => String(id || '').trim()).filter((id) => id)))
const hidden = new Set()
if (ids.length) for (const row of ec.entity.find('moqui.security.UserPreference').condition('userId', 'in', ids)
        .condition('preferenceKey', 'CHAT_NOTIFY_PREVIEW').disableAuthz().list()) {
    const value = String(row.preferenceValue || '').trim()
    if (value === 'N' || value === 'false') hidden.add(row.userId)
}
previewUserIdList = ids.filter((id) => !hidden.has(id))
noPreviewUserIdList = ids.filter((id) => hidden.has(id))

offUserIdList = []
const ids = Array.from(new Set(Array.from(userIdList || []).map((id) => String(id || '').trim()).filter((id) => id)))
if (ids.length) for (const row of ec.entity.find('moqui.security.UserPreference').condition('userId', 'in', ids)
        .condition('preferenceKey', 'CHAT_READ_RECEIPTS').disableAuthz().list()) {
    const value = String(row.preferenceValue || '').trim()
    if (value === 'N' || value === 'false') offUserIdList.push(row.userId)
}

const groups = ec.service.sync().name('org.moqui.impl.ChatServices.get#NotifyPreviewUsers').parameter('userIdList', userIdList).call()
const text = String(bodyText || '')
const summary = text.length > 120 ? text.slice(0, 119) + '…' : text
const send = (users, withText) => {
    if (!users || !users.length) return
    try {
        const message = {roomName: roomName || chatRoomId, chatRoomId: chatRoomId, eventSeq: eventSeq, authorUserId: authorUserId,
            authorName: authorName || authorUserId}
        if (withText) message.summary = summary
        const nm = ec.makeNotificationMessage().topic('ChatMention').userIds(users).message(message).reason('mention')
            .record('moqui.chat.ChatRoom', chatRoomId).actorUserId(authorUserId)
        if (!withText) nm.title(ec.l10n.localize('${authorName} mentioned you in ${roomName}'))
        if (roomUrl) nm.link(roomUrl)
        nm.send()
    } catch (err) {
        ec.logger.error(`Could not notify the mentions of chat message ${chatRoomId}::${eventSeq}: ${err && err.message ? err.message : err}`)
    }
}
if (encrypted) { send(userIdList, false); return }
send(groups.previewUserIdList, true)
send(groups.noPreviewUserIdList, false)

const VISIBILITIES = {members: 'CrvMembers', users: 'CrvUsers', record: 'CrvRecord'}
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.isMember) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (access.room.roomTypeEnumId === 'CrtDirect') { ec.message.addError(ec.l10n.localize('A direct room has no settings')); return }
const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).forUpdate(true).one()
const changes = []
const given = (value) => value !== undefined && value !== null
if (given(roomName) || given(topic) || given(avatarLocation)) {
    if (!access.canModerate) { ec.message.addError(ec.l10n.localize('Only a moderator or owner may change the room')); return }
    if (given(roomName)) {
        const name = String(roomName).trim()
        if (!name) { ec.message.addError(ec.l10n.localize('A room needs a name')); return }
        if (name !== room.roomName) { room.set('roomName', name); changes.push({action: 'renamed', roomName: name}) }
    }
    if (given(topic) && (topic || null) !== (room.topic || null)) { room.set('topic', topic || null); changes.push({action: 'topic', topic: topic || null}) }
    if (given(avatarLocation)) room.set('avatarLocation', avatarLocation || null)
}
if (given(visibilityEnumId) || given(retentionDays) || given(archived)) {
    if (!access.isOwner) { ec.message.addError(ec.l10n.localize('Only an owner may change who may join, the retention or the archive')); return }
    if (given(visibilityEnumId)) {
        const visibility = VISIBILITIES[visibilityEnumId] || visibilityEnumId
        const allowed = room.roomTypeEnumId === 'CrtRecord' ? ['CrvMembers', 'CrvRecord'] : ['CrvMembers', 'CrvUsers']
        if (room.encrypted === 'Y' && visibility !== 'CrvMembers') { ec.message.addError(ec.l10n.localize('An encrypted room is for its members only')); return }
        if (!allowed.includes(visibility)) { ec.message.addError(`A room of this type may not have visibility ${visibilityEnumId}`); return }
        room.set('visibilityEnumId', visibility)
    }
    if (given(retentionDays)) room.set('retentionDays', retentionDays > 0 ? retentionDays : null)
    if (given(archived) && archived !== !!room.archivedDate) {
        room.set('archivedDate', archived ? ec.user.nowTimestamp : null)
        changes.push({action: archived ? 'archived' : 'unarchived'})
    }
}
room.update()
for (const change of changes) {
    ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
        eventTypeEnumId: 'CetSystem', senderUserId: ec.user.userId, content: change}).call()
    if (ec.message.hasError()) return
}
const memberIds = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('leftDate', null)
        .selectField('userId').list()).map((row) => row.userId).filter((id) => id)
ec.service.sync().name('org.moqui.impl.ChatServices.record#UserChange').parameters({userIdList: memberIds, changeKind: 'room',
    chatRoomId: chatRoomId, change: {reason: changes.length ? changes[changes.length - 1].action : 'details'},
    pushMessage: {kind: 'room', action: 'changed', chatRoomId: chatRoomId}}).call()

const ROLES = {owner: 'CmrOwner', moderator: 'CmrModerator', member: 'CmrMember', agent: 'CmrAgent'}
addedUserIdList = []
const me = ec.user.userId
if (!me) { ec.message.addError(ec.l10n.localize('No user')); return }
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const room = access.room
if (access.isArchived) { ec.message.addError(ec.l10n.localize('The room is archived')); return }
let targets = Array.from(new Set((userIdList || []).concat(userId ? [userId] : []).map((id) => String(id || '').trim()).filter((id) => id)))
const joining = !targets.length || (targets.length === 1 && targets[0] === me && !access.isMember)
if (!targets.length) targets = [me]
let role = ROLES[roleEnumId] || roleEnumId || 'CmrMember'
if (joining) {
    if (access.isMember) return
    if (!access.canJoin) { ec.message.addError(ec.l10n.localize('You may not join this room')); return }
    role = 'CmrMember'
} else {
    if (!access.isMember) { ec.message.addError(ec.l10n.localize('Join the room before adding others')); return }
    if (room.roomTypeEnumId === 'CrtDirect') { ec.message.addError(ec.l10n.localize('A direct room has fixed members: start a new direct message')); return }
    // C4-SMS: a number pair's room has the users its number reaches (SmsServices ensure#PairRoom), nobody else
    if (room.roomTypeEnumId === 'CrtExternal') { ec.message.addError(ec.l10n.localize('A conversation with a phone number has the members its number reaches')); return }
    if (!Object.values(ROLES).includes(role)) { ec.message.addError(`Unknown member role ${roleEnumId}`); return }
    if ((role !== 'CmrMember' || agentRef) && !access.canModerate) { ec.message.addError(ec.l10n.localize('Only a moderator or owner may give a role')); return }
    if (role === 'CmrOwner' && !access.isOwner) { ec.message.addError(ec.l10n.localize('Only an owner may add an owner')); return }
    const found = new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', targets)
            .condition(ec.entity.conditionFactory.makeCondition('disabled', 'not-equals', 'Y', true))
            .selectField('userId').disableAuthz().list()).map((row) => row.userId))
    const missing = targets.filter((id) => !found.has(id))
    if (missing.length) { ec.message.addError(`User ${missing.join(', ')} not found`); return }
    // nobody adds an external user (EXTERNAL_USER) to a room bound to a record
    if (room.roomTypeEnumId === 'CrtRecord' || room.visibilityEnumId === 'CrvRecord' || room.recordEntityName) {
        const outside = ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers').parameter('userIdList', targets)
                .disableAuthz().call()
        if (!outside || outside.anyExternal !== false) { ec.message.addError(`User ${(outside?.externalUserIdList || targets).join(', ')} may not be in a record room`); return }
    }
