    if (role === 'CmrAgent' && room.encrypted) { ec.message.addError(ec.l10n.localize('An agent cannot read an encrypted room')); return }
    if (role === 'CmrAgent') {
        const agents = new Set(Array.from(ec.entity.find('moqui.agent.AgentDefinition').condition('chatUserId', 'in', targets)
                .selectField('chatUserId').disableAuthz().list()).map((row) => row.chatUserId))
        const people = targets.filter((id) => !agents.has(id))
