const ownLevels = room.roomTypeEnumId === 'CrtDirect' ? {} : ec.service.sync().name('org.moqui.impl.ChatServices.get#DefaultNotifyLevels')
        .parameter('userIdList', targets).call().levelMap || {}
let roomLocked = false
const actorOf = ec.service.sync().name('org.moqui.impl.ChatServices.get#LocalActors').parameter('userIdList', targets)
        .disableAuthz().call()?.actorMap || {}
