    const level = ownLevels[target] || roomLevel
    let row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', target).one()
    // no row yet: a lock on a missing row locks nothing, so two joins at once (a double click, two tabs) would
    // both create it. Lock the ChatRoom row, as append#Event does next, and look again: the second waits for
    // the first to commit, then finds its member and adds nobody.
    if (!row) {
        if (!roomLocked) {
            ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).selectField('chatRoomId').forUpdate(true).disableAuthz().one()
            roomLocked = true
        }
        row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', target).forUpdate(true).one()
    }
    if (row && !row.leftDate) continue
    if (row) {
        row.setFields({leftDate: null, joinedDate: now, roleEnumId: role, agentRef: agentRef || null,
            lastReadEventSeq: Math.max(Number(row.lastReadEventSeq || 0), lastSeq), addedByUserId: me}, true, null, null)
        row.update()
    } else {
        row = ec.entity.makeValue('moqui.chat.ChatRoomMember')
        row.setFields({chatRoomId: chatRoomId, chatActorId: actorOf[target], userId: target, roleEnumId: role, agentRef: agentRef || null, joinedDate: now,
            lastReadEventSeq: lastSeq, notificationLevelEnumId: level, isPinned: 'N', isMuted: 'N', addedByUserId: me}, true, null, null)
        row.create()
    }
