}
for (const target of addedUserIdList) {
    const appended = ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
        eventTypeEnumId: 'CetMembership', senderUserId: me, content: {action: joining ? 'join' : 'add', userId: target,
        roleEnumId: role, byUserId: me}}).call()
    if (ec.message.hasError()) return
    // the membership event itself is read for the new member
    ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', target)
