        userIdList: [target], message: {kind: 'room', action: 'joined', chatRoomId: chatRoomId,
        changeSeq: (appended.changeSeqMap || {})[target] ?? null}}).call()
}

const me = ec.user.userId
if (!userId && !chatActorId) userId = me
