if (ec.message.hasError()) return
if (!access.isMember) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const room = access.room
const isDirect = room.roomTypeEnumId === 'CrtDirect'
const row = userId ? ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', userId).one()
        : ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('chatActorId', chatActorId).one()
// a local user's actor named by chatActorId is that user: the same checks, and the user hears of it
if (row && !userId && row.userId) userId = row.userId
const self = !!userId && userId === me
if (!row || row.leftDate) { if (!self) ec.message.addError(`User ${userId || chatActorId} is not in the room`); return }
if (!self) {
    if (isDirect) { ec.message.addError(ec.l10n.localize('A direct room has fixed members')); return }
    if (!access.canModerate) { ec.message.addError(ec.l10n.localize('Only a moderator or owner may take a member out')); return }
    if (row.roleEnumId === 'CmrOwner' && !access.isOwner) { ec.message.addError(ec.l10n.localize('Only an owner may take an owner out')); return }
}
const now = ec.user.nowTimestamp
row.set('leftDate', now)
row.update()
let leftSeq = null
if (!isDirect) {
    const left = ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
        eventTypeEnumId: 'CetMembership', senderUserId: me, content: {action: self ? 'leave' : 'remove', userId: userId || null,
        chatActorId: row.chatActorId ?? null, byUserId: me}}).call()
    leftSeq = userId ? ((left && left.changeSeqMap) || {})[userId] ?? null : null
    if (ec.message.hasError()) return
    if (row.roleEnumId === 'CmrOwner') {
        const remaining = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('leftDate', null)
                .condition('roleEnumId', 'not-equals', 'CmrAgent').orderBy('joinedDate').list()).filter((member) => member.userId)
        if (remaining.length && !remaining.some((member) => member.roleEnumId === 'CmrOwner')) {
            const heir = remaining.find((member) => member.roleEnumId === 'CmrModerator') || remaining[0]
            heir.set('roleEnumId', 'CmrOwner')
            heir.update()
            ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
                eventTypeEnumId: 'CetMembership', senderUserId: me, content: {action: 'role', userId: heir.userId, roleEnumId: 'CmrOwner', byUserId: me}}).call()
        }
    }
}
if (!userId) return
// a direct room is left with no event: the user's change is recorded here
if (isDirect) ec.service.sync().name('org.moqui.impl.ChatServices.record#UserChange').parameters({userIdList: [userId],
    changeKind: 'membership', chatRoomId: chatRoomId, change: {action: 'left', byUserId: me},
    pushMessage: {kind: 'room', action: 'left', chatRoomId: chatRoomId}}).call()
else ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatUser:' + userId,
    userIdList: [userId], message: {kind: 'room', action: 'left', chatRoomId: chatRoomId, changeSeq: leftSeq}}).call()
ec.service.sync().name('org.moqui.impl.ChatServices.publish#ChatCounts').parameter('userIdList', [userId]).call()

const ROLES = {owner: 'CmrOwner', moderator: 'CmrModerator', member: 'CmrMember', agent: 'CmrAgent'}
const role = ROLES[roleEnumId] || roleEnumId
if (!Object.values(ROLES).includes(role)) { ec.message.addError(`Unknown member role ${roleEnumId}`); return }
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.isMember) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (access.room.roomTypeEnumId === 'CrtDirect') { ec.message.addError(ec.l10n.localize('A direct room has no roles')); return }
if (!access.canModerate) { ec.message.addError(ec.l10n.localize('Only a moderator or owner may give a role')); return }
const row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', userId).one()
if (!row || row.leftDate) { ec.message.addError(`User ${userId} is not in the room`); return }
if (!access.isOwner && (row.roleEnumId === 'CmrOwner' || role === 'CmrOwner' || role === 'CmrAgent')) {
    ec.message.addError(ec.l10n.localize('Only an owner may change an owner or make an owner or agent')); return }
if (role === 'CmrAgent' && access.room.encrypted) { ec.message.addError(ec.l10n.localize('An agent cannot read an encrypted room')); return }
if (role === 'CmrAgent' && !ec.entity.find('moqui.agent.AgentDefinition').condition('chatUserId', userId).disableAuthz().count()) {
    ec.message.addError(`User ${userId} is no agent's chat user`); return }
if (row.roleEnumId === 'CmrOwner' && role !== 'CmrOwner') {
    const owners = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('leftDate', null)
