ec.service.sync().name('org.moqui.impl.ChatServices.record#UserChange').parameters({userIdList: [me], changeKind: 'settings',
    chatRoomId: chatRoomId, change: settings, pushMessage: Object.assign({kind: 'room', action: 'settings', chatRoomId: chatRoomId}, settings)}).call()
ec.service.sync().name('org.moqui.impl.ChatServices.publish#ChatCounts').parameter('userIdList', [me]).call()

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
const CODES = {CetMessage: 'message', CetEdit: 'edit', CetReaction: 'reaction', CetRedaction: 'redaction',
    CetMembership: 'membership', CetPin: 'pin', CetCall: 'call', CetPoll: 'poll', CetSystem: 'system'}
const SHOWN = ['CetMessage', 'CetMembership', 'CetPin', 'CetCall', 'CetPoll', 'CetSystem']
room = null; access = null; eventList = []; hasMoreBefore = false; hasMoreAfter = false; lastReadEventSeq = null; memberList = []
const roomOut = ec.service.sync().name('org.moqui.impl.ChatServices.get#Room').parameters({chatRoomId: chatRoomId,
    recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError() || !roomOut.room) return
room = roomOut.room; access = roomOut.access; memberList = roomOut.memberList
chatRoomId = room.chatRoomId
lastReadEventSeq = roomOut.member ? roomOut.member.lastReadEventSeq : null
const me = ec.user.userId
const size = Math.max(1, Math.min(200, Number(limit) || 50))
const cf = ec.entity.conditionFactory
const base = () => {
    let find = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId)
    if (eventSeq != null) return find.condition('eventSeq', eventSeq).condition('eventTypeEnumId', 'in', SHOWN)
    if (pinnedOnly) return find.condition('eventTypeEnumId', 'CetMessage').condition('pinnedDate', 'not-equals', null).condition('redactedDate', null)
    if (threadRootEventSeq != null) return find.condition('eventTypeEnumId', 'CetMessage').condition(cf.makeCondition([
        cf.makeCondition('eventSeq', 'equals', threadRootEventSeq), cf.makeCondition('threadRootEventSeq', 'equals', threadRootEventSeq)], 'or'))
    return find.condition('eventTypeEnumId', 'in', SHOWN).condition('threadRootEventSeq', null)
}
let rows
if (eventSeq != null) {
    rows = Array.from(base().list())
} else if (pinnedOnly) {
    rows = Array.from(base().orderBy('-pinnedDate').limit(size + 1).list())
    hasMoreAfter = rows.length > size
    rows = rows.slice(0, size)
} else if (aroundSeq != null) {
    const half = Math.max(1, Math.floor(size / 2))
    const older = Array.from(base().condition('eventSeq', 'less', aroundSeq).orderBy('-eventSeq').limit(half + 1).list())
    const newer = Array.from(base().condition('eventSeq', 'greater-equals', aroundSeq).orderBy('eventSeq').limit(size - half + 1).list())
    hasMoreBefore = older.length > half
    hasMoreAfter = newer.length > size - half
    rows = older.slice(0, half).reverse().concat(newer.slice(0, size - half))
} else if (afterSeq != null) {
    rows = Array.from(base().condition('eventSeq', 'greater', afterSeq).orderBy('eventSeq').limit(size + 1).list())
    hasMoreAfter = rows.length > size
    rows = rows.slice(0, size)
    hasMoreBefore = base().condition('eventSeq', 'less-equals', afterSeq).count() > 0
} else {
    let find = base()
    if (beforeSeq != null) find = find.condition('eventSeq', 'less', beforeSeq)
    rows = Array.from(find.orderBy('-eventSeq').limit(size + 1).list())
    hasMoreBefore = rows.length > size
    rows = rows.slice(0, size).reverse()
    hasMoreAfter = beforeSeq != null && base().condition('eventSeq', 'greater-equals', beforeSeq).count() > 0
}
if (!rows.length) return
const seqs = rows.map((row) => Number(row.eventSeq))
// the latest edit of each edited message
const editSeqs = rows.filter((row) => row.lastEditEventSeq != null && !row.redactedDate).map((row) => Number(row.lastEditEventSeq))
const edits = {}
if (editSeqs.length) for (const edit of ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId)
        .condition('eventSeq', 'in', editSeqs).list()) {
    edits[Number(edit.editsEventSeq)] = parse(edit.contentJson)
    edits[Number(edit.editsEventSeq)].__seq = Number(edit.eventSeq)
    edits[Number(edit.editsEventSeq)].__sent = toMillis(edit.sentDate)
}
const sealedReactions = {}
// the reactions that stand
const reactions = {}
for (const reaction of ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventTypeEnumId', 'CetReaction')
        .condition('relatesToEventSeq', 'in', seqs).condition('redactedDate', null).orderBy('eventSeq').list()) {
    const reactionContent = parse(reaction.contentJson)
    const key = reactionContent.key
    const target = Number(reaction.relatesToEventSeq)
    // an encrypted reaction (C7): its key is for the browser to read
    if (reactionContent.encrypted) {
        (sealedReactions[target] = sealedReactions[target] || []).push({eventSeq: Number(reaction.eventSeq),
            senderUserId: reaction.senderUserId ?? null, sentDate: toMillis(reaction.sentDate), encrypted: reactionContent.encrypted})
        continue
    }
    if (!key) continue
    const byKey = reactions[target] = reactions[target] || {}
    const entry = byKey[key] = byKey[key] || {key: key, count: 0, userIds: [], mine: false}
    const who = reaction.senderUserId || reaction.senderActorId
    if (entry.userIds.includes(who)) continue
    entry.userIds.push(who)
    entry.count++
    if (reaction.senderUserId === me) entry.mine = true
}
// the messages replied to that are not on this page
const onPage = {}
rows.forEach((row) => { onPage[Number(row.eventSeq)] = row })
const replySeqs = Array.from(new Set(rows.filter((row) => row.replyToEventSeq != null).map((row) => Number(row.replyToEventSeq)).filter((seq) => !onPage[seq])))
const replied = Object.assign({}, onPage)
