        .condition('eventSeq', 'in', Array.from(new Set(rows.map((row) => Number(row.eventSeq))))).list()) events[Number(row.eventSeq)] = row
const userIds = Array.from(new Set(Object.values(events).map((row) => row.senderUserId).filter((id) => id)))
const names = {}
if (userIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds)
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
for (const row of rows) {
    const event = events[Number(row.eventSeq)]
    if (!event || event.redactedDate) continue
    fileList.push({chatAttachmentId: row.chatAttachmentId, eventSeq: Number(row.eventSeq), attachmentSeq: Number(row.attachmentSeq || 0),
        fileName: sealed ? null : row.fileName ?? null, contentType: sealed ? null : row.contentType ?? null, encrypted: sealed, fileSize: row.fileSize != null ? Number(row.fileSize) : null,
        senderUserId: event.senderUserId ?? null, senderName: event.senderUserId ? names[event.senderUserId] || event.senderUserId : null,
        sentDate: toMillis(event.sentDate), threadRootEventSeq: event.threadRootEventSeq != null ? Number(event.threadRootEventSeq) : null})
}

const escape = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
eventSeq = null; event = null; duplicate = false; reasonCode = null
const me = ec.user.userId
// a poll's question and votes are read by the server: none in an encrypted room (C7)
if (ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).condition('encrypted', 'Y').count()) {
    reasonCode = 'encryptedRoom'; ec.message.addError(ec.l10n.localize('An encrypted room has no polls')); return }
const asked = String(question || '').replace(/\s+/g, ' ').trim()
if (!asked) { ec.message.addError(ec.l10n.localize('A poll needs a question')); return }
if (asked.length > 500) { ec.message.addError(ec.l10n.localize('The question is too long')); return }
const options = []
for (const option of Array.from(optionList || [])) {
    const shown = String(option ?? '').replace(/\s+/g, ' ').trim()
    if (!shown) continue
    if (shown.length > 200) { ec.message.addError(ec.l10n.localize('An option is up to 200 characters')); return }
    if (options.some((other) => other.toLowerCase() === shown.toLowerCase())) { ec.message.addError(`The option ${shown} is there twice`); return }
    options.push(shown)
}
if (options.length < 2 || options.length > 10) { ec.message.addError(ec.l10n.localize('A poll has 2 to 10 options')); return }
const closes = closesDate != null ? Number(closesDate) : null
if (closes != null && closes <= Number(ec.user.nowTimestamp)) { ec.message.addError(ec.l10n.localize('A poll closes later than now')); return }
const sent = ec.service.sync().name('org.moqui.impl.ChatServices.send#Message').parameters({chatRoomId: chatRoomId,
    body: '<p>' + escape(asked) + '</p>', threadRootEventSeq: threadRootEventSeq ?? null, clientRef: clientRef || null, roomUrl: roomUrl || null}).call()
if (ec.message.hasError()) return
eventSeq = sent.eventSeq
event = sent.event
if (sent.duplicate) { duplicate = true; return }
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).one()
const content = JSON.parse(row.contentJson || '{}')
content.poll = {question: asked}
row.set('contentJson', JSON.stringify(content))
row.update()
const poll = ec.entity.makeValue('moqui.chat.ChatPoll')
poll.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, question: asked, isAnonymous: anonymous ? 'Y' : 'N', allowMultiple: multiple ? 'Y' : 'N',
    closesDate: closesDate ?? null, createdByUserId: me, voterCount: 0}, true, null, null)
poll.create()
options.forEach((text, index) => {
    const option = ec.entity.makeValue('moqui.chat.ChatPollOption')
    option.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, optionSeq: index + 1, optionText: text, voteCount: 0}, true, null, null)
    option.create()
})
const states = ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId,
    eventSeqList: [eventSeq]}).call().pollMap || {}
const shared = ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId,
    eventSeqList: [eventSeq], shared: true}).call().pollMap || {}
event = Object.assign({}, event, {poll: states[eventSeq] || null})
ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {poll: shared[eventSeq] || null}}).call()

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
pollMap = {}
const seqs = Array.from(new Set(Array.from(eventSeqList || []).map(Number).filter((seq) => !Number.isNaN(seq))))
if (!seqs.length) return
const me = ec.user.userId
const now = Number(ec.user.nowTimestamp)
const polls = Array.from(ec.entity.find('moqui.chat.ChatPoll').condition('chatRoomId', chatRoomId).condition('eventSeq', 'in', seqs).list())
if (!polls.length) return
const options = {}, votes = {}
for (const row of ec.entity.find('moqui.chat.ChatPollOption').condition('chatRoomId', chatRoomId).condition('eventSeq', 'in', seqs)
        .orderBy('optionSeq').list()) (options[Number(row.eventSeq)] = options[Number(row.eventSeq)] || []).push(row)
for (const row of ec.entity.find('moqui.chat.ChatPollVote').condition('chatRoomId', chatRoomId).condition('eventSeq', 'in', seqs)
        .orderBy('votedDate').list()) (votes[Number(row.eventSeq)] = votes[Number(row.eventSeq)] || []).push(row)
for (const poll of polls) {
    const seq = Number(poll.eventSeq)
    const anonymous = poll.isAnonymous === 'Y'
    const cast = votes[seq] || []
    const closesAt = toMillis(poll.closesDate)
    const state = {question: poll.question ?? null, anonymous: anonymous, multiple: poll.allowMultiple === 'Y', closesDate: closesAt,
        closedDate: toMillis(poll.closedDate), closed: !!poll.closedDate || (closesAt != null && closesAt <= now),
        createdByUserId: poll.createdByUserId ?? null, voterCount: Number(poll.voterCount || 0), totalVotes: 0,
        options: (options[seq] || []).map((row) => {
            const id = Number(row.optionSeq)
            const option = {id: id, text: row.optionText ?? '', voteCount: Number(row.voteCount || 0),
                voterIds: anonymous ? [] : cast.filter((vote) => Number(vote.optionSeq) === id).map((vote) => vote.userId)}
            if (!shared) option.mine = cast.some((vote) => Number(vote.optionSeq) === id && vote.userId === me)
            return option
        })}
    state.totalVotes = state.options.reduce((sum, option) => sum + option.voteCount, 0)
    if (!shared) state.mine = cast.filter((vote) => vote.userId === me).map((vote) => Number(vote.optionSeq))
    pollMap[seq] = state
}

poll = null
const me = ec.user.userId
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (!access.canPost) { ec.message.addError(access.isArchived ? 'The room is archived' : 'Join the room to vote'); return }
const row = ec.entity.find('moqui.chat.ChatPoll').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).forUpdate(true).one()
if (!row) { ec.message.addError(`Poll ${eventSeq} not found in the room`); return }
const now = Number(ec.user.nowTimestamp)
if (row.closedDate || (row.closesDate != null && Number(row.closesDate) <= now)) { ec.message.addError(ec.l10n.localize('The poll is closed')); return }
const chosen = Array.from(new Set(Array.from(optionIdList || []).map((id) => Number(id)).filter((id) => !Number.isNaN(id))))
if (chosen.length > 1 && row.allowMultiple !== 'Y') { ec.message.addError(ec.l10n.localize('Choose one option')); return }
const options = Array.from(ec.entity.find('moqui.chat.ChatPollOption').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).list())
const byId = {}
options.forEach((option) => { byId[Number(option.optionSeq)] = option })
const unknown = chosen.filter((id) => !byId[id])
if (unknown.length) { ec.message.addError(`Option ${unknown.join(', ')} not found in the poll`); return }
const before = Array.from(ec.entity.find('moqui.chat.ChatPollVote').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq)
        .condition('userId', me).list()).map((vote) => Number(vote.optionSeq))
const same = before.length === chosen.length && before.every((id) => chosen.includes(id))
if (!same) {
    ec.entity.find('moqui.chat.ChatPollVote').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).condition('userId', me).deleteAll()
    for (const id of before) if (byId[id]) byId[id].set('voteCount', Math.max(0, Number(byId[id].voteCount || 0) - 1))
    const myActor = chosen.length ? (ec.service.sync().name('org.moqui.impl.ChatServices.get#LocalActors').parameter('userIdList', [me])
