            votedDate: ec.user.nowTimestamp}, true, null, null)
        vote.create()
        byId[id].set('voteCount', Number(byId[id].voteCount || 0) + 1)
    }
    for (const option of options) if (before.includes(Number(option.optionSeq)) || chosen.includes(Number(option.optionSeq))) option.update()
    const voters = new Set(Array.from(ec.entity.find('moqui.chat.ChatPollVote').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq)
            .selectField('chatActorId').list()).map((vote) => vote.chatActorId))
