if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const row = ec.entity.find('moqui.chat.ChatPoll').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).forUpdate(true).one()
if (!row) { ec.message.addError(`Poll ${eventSeq} not found in the room`); return }
if (!(row.createdByUserId === me && access.isMember) && !access.canModerate) { ec.message.addError(ec.l10n.localize('Only the poll\'s creator or a moderator may close it')); return }
if (!row.closedDate) {
    row.set('closedDate', ec.user.nowTimestamp)
    row.set('closedByUserId', me)
    row.update()
    ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
        fields: {poll: (ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId,
            eventSeqList: [eventSeq], shared: true}).call().pollMap || {})[eventSeq] || null}}).call()
}
poll = (ec.service.sync().name('org.moqui.impl.ChatServices.get#PollStates').parameters({chatRoomId: chatRoomId, eventSeqList: [eventSeq]})
        .call().pollMap || {})[eventSeq] || null

eventSeq = null
if (!ec.artifactExecution.authzDisabled()) { ec.message.addError(ec.l10n.localize('An agent card is sent by the agent runtime')); return }
const escape = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
if (ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).condition('encrypted', 'Y').count()) {
    ec.message.addError(ec.l10n.localize('An agent cannot post in an encrypted room')); return }
const kind = String(assist.kind || '')
if (!['approval', 'question', 'reply'].includes(kind)) { ec.message.addError(`An agent card is an approval, a question or a reply, not ${kind}`); return }
const html = body ? String(body) : '<p>' + escape(bodyText || assist.summary || assist.title || kind) + '</p>'
const sent = ec.service.sync().name('org.moqui.impl.ChatServices.send#Message').parameters({chatRoomId: chatRoomId,
    senderUserId: senderUserId, body: html, threadRootEventSeq: threadRootEventSeq ?? null}).call()
if (ec.message.hasError()) return
eventSeq = sent.eventSeq
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).one()
const content = JSON.parse(row.contentJson || '{}')
content.assist = Object.assign({}, assist, {kind: kind, state: assist.state || (kind === 'reply' ? 'done' : 'pending')})
row.set('contentJson', JSON.stringify(content))
row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {assist: content.assist}}).call()

if (String(System.getProperty('chat_link_previews') || '').trim() === 'false') return
if (!/https?:\/\//i.test(String(body || ''))) return
if (ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).condition('encrypted', 'Y').count()) return
if (senderUserId) {
    const pref = ec.entity.find('moqui.security.UserPreference').condition('userId', senderUserId).condition('preferenceKey', 'CHAT_LINK_PREVIEWS')
            .disableAuthz().one()
    const value = pref ? String(pref.preferenceValue || '').trim() : ''
    if (value === 'N' || value === 'false') return
}
try {
    ec.service.special().name('org.moqui.impl.ChatServices.fetch#LinkPreviews').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq}).registerOnCommit()
} catch (err) {
    ec.logger.error(`Could not queue the link previews of chat message ${chatRoomId}::${eventSeq}: ${err && err.message ? err.message : err}`)
}

const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
linkPreviews = []
ec.artifactExecution.disableAuthz()
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).one()
if (!row || row.eventTypeEnumId !== 'CetMessage' || row.redactedDate || parse(row.linkPreviewJson).removed) return
let body = parse(row.contentJson).body
if (row.lastEditEventSeq != null) {
    const edit = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', row.lastEditEventSeq).one()
    if (edit && parse(edit.contentJson).body != null) body = parse(edit.contentJson).body
}
const urls = ec.service.sync().name('org.moqui.impl.ChatServices.extract#LinkUrls').parameter('body', body || '').call().urlList || []
for (const link of urls) {
