    row.setFields(Object.assign({urlHash: urlHash}, fields), true, null, null)
    row.create()
}
preview = shown(row)

const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).forUpdate(true).one()
if (!row || row.eventTypeEnumId !== 'CetMessage' || row.redactedDate) { ec.message.addError(`Message ${eventSeq} not found in the room`); return }
if (row.senderUserId !== ec.user.userId) { ec.message.addError(ec.l10n.localize('Only the sender removes the previews of a message')); return }
row.set('linkPreviewJson', '{"removed":true}')
row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {linkPreviews: []}}).call()

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const cf = ec.entity.conditionFactory
eventList = []; total = 0; reasonCode = null
const me = ec.user.userId
const text = String(searchText || '').trim()
if (!me || !text) return
const size = Math.max(1, Math.min(100, Number(limit) || 20))
const offset = Math.max(0, Number(pageIndex) || 0) * size
let myRooms = []
let includePublic = true
if (chatRoomId) {
    const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
    if (ec.message.hasError()) return
    if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
    // the server has no text of an encrypted room (C7)
    if (access.room.encrypted) { reasonCode = 'encryptedRoom'; ec.message.addError(ec.l10n.localize('An encrypted room is not searched on the server')); return }
    myRooms = [chatRoomId]
    includePublic = false
} else {
    const directOrCurrent = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).selectField('chatRoomId')
            .selectField('leftDate').list())
    const ids = directOrCurrent.map((row) => row.chatRoomId)
    const directIds = new Set(ids.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', ids)
            .condition('roomTypeEnumId', 'CrtDirect').selectField('chatRoomId').list()).map((row) => row.chatRoomId) : [])
    myRooms = directOrCurrent.filter((row) => !row.leftDate || directIds.has(row.chatRoomId)).map((row) => row.chatRoomId)
    // an external user (EXTERNAL_USER; a failed check counts as external): no record room, no public room not joined
    if (ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers').parameter('userIdList', [me]).disableAuthz()
            .call()?.anyExternal !== false) {
        includePublic = false
        const recordIds = new Set(myRooms.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', myRooms)
                .selectField('chatRoomId').selectField('roomTypeEnumId').selectField('visibilityEnumId').selectField('recordEntityName').list())
                .filter((row) => row.roomTypeEnumId === 'CrtRecord' || row.visibilityEnumId === 'CrvRecord' || row.recordEntityName)
                .map((row) => row.chatRoomId) : [])
        myRooms = myRooms.filter((id) => !recordIds.has(id))
    }
}
// the encrypted rooms (C7) are left out: the server has no text of them
if (myRooms.length) {
    const sealed = new Set(Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', myRooms).condition('encrypted', 'Y')
            .selectField('chatRoomId').list()).map((row) => row.chatRoomId))
    if (sealed.size) myRooms = myRooms.filter((id) => !sealed.has(id))
}
const names = {}
const roomNames = {}
const finish = () => {
    const userIds = Array.from(new Set(eventList.map((item) => item.senderUserId).filter((id) => id)))
    if (userIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds)
            .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
        names[account.userId] = account.userFullName || account.username || account.userId
    const roomIds = Array.from(new Set(eventList.map((item) => item.chatRoomId)))
    if (roomIds.length) for (const room of ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', roomIds)
            .selectField('chatRoomId').selectField('roomName').list()) roomNames[room.chatRoomId] = room.roomName
    for (const item of eventList) {
        if (!item.senderName && item.senderUserId) item.senderName = names[item.senderUserId] || item.senderUserId
        if (!item.roomName) item.roomName = roomNames[item.chatRoomId] || null
    }
}
if (ec.search.isAvailable() && ec.search.indexExists({documentType: 'MoquiChatEvent'})) {
